package Operatorsinjava;

public class operator8 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int i=55;
		int j=6;

// Assignment operator
		i+=5; // 60
		System.out.println(i);

		i-=5; //55
		System.out.println(i);

		i*=5;//275
		System.out.println(i);

		i/=5;//55
		System.out.println(i);

		i%=5;//0
		System.out.println(i);

		i+=45;//45
		System.out.println(i);

	}

}
